def run_query(target):
    # If target is a path to an existing file, read SQL from the file;
    # otherwise treat target as a raw SQL string.
    if isinstance(target, str) and os.path.isfile(target):
        with open(target, 'r') as f:
            sql = f.read()
    else:
        sql = target

    conn = psycopg2.connect(**DB_CONFIG)
    conn.autocommit = True
    try:
        cur = conn.cursor()
        cur.execute(sql)

        if cur.description is not None:
            # SELECT-like query: print pipe-separated table
            headers = [desc[0] for desc in cur.description]
            rows = cur.fetchall()
            print(" | ".join(headers))
            print("-+-".join("-" * len(h) for h in headers))
            for row in rows:
                print(" | ".join("" if v is None else str(v) for v in row))
        else:
            # Non-SELECT (INSERT/UPDATE/DDL/etc.)
            rc = cur.rowcount
            print(f"Query executed successfully. Rows affected: {rc}")

        cur.close()
    finally:
        conn.close()


